import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const localesDir = path.resolve(__dirname, '../locales/zh-CN')
const outputPath = path.resolve(__dirname, '../src/typings/i18n.d.ts')

const GENERATED_HEADER = `/**
 * This file is auto-generated by scripts/generate-i18n-types.mjs
 * DO NOT EDIT MANUALLY
 */`

const KEY_PATHS_NOTE = `/**
 * 语言包中可翻译叶子 key 的扁平点分联合（首段为语言包文件名命名空间）。
 *
 * 为什么生成而不是在类型层推导：用递归条件类型在 5000+ key 上做路径展开，
 * 每次 vue-tsc 都要重算，是实打实的类型检查性能风险；这里在生成期一次性算清。
 *
 * 数组值按终止路径处理（不下钻元素）：数组是 UI 列表，经 tm() 消费，
 * 不会被某个点分 t() key 直接寻址。
 */`

/**
 * 深度优先收集点分 key 路径。
 * - 字符串值 -> 叶子路径
 * - 数组值 -> 终止路径（不下钻，避免生成 `x.y.0.title` 这类非 t() key）
 * - 对象值 -> 继续下钻
 * @param {unknown} value 当前节点
 * @param {string} prefix 当前前缀（不含尾部点）
 * @param {string[]} out 收集结果
 */
function collectKeyPaths(value, prefix, out) {
  if (typeof value !== 'object' || value === null) {
    out.push(prefix)
    return
  }
  if (Array.isArray(value)) {
    out.push(prefix)
    return
  }
  for (const [key, child] of Object.entries(value)) {
    collectKeyPaths(child, prefix ? `${prefix}.${key}` : key, out)
  }
}

/**
 * 渲染 `src/typings/i18n.d.ts` 全文。
 * @param {Record<string, unknown>} packs 语言包（key = 文件名去扩展名，顺序需与 readdirSync 一致）
 */
function buildTypeContent(packs) {
  const keyPaths = []
  for (const [part, content] of Object.entries(packs)) {
    collectKeyPaths(content, part, keyPaths)
  }

  const union = keyPaths.map((key) => `  | ${JSON.stringify(key)}`).join('\n')
  return {
    keyPathCount: keyPaths.length,
    content: `${GENERATED_HEADER}

export type I18nKeys = ${JSON.stringify(packs, null, 2)}

${KEY_PATHS_NOTE}
export type I18nKeyPaths =
${union}
`
  }
}

function generateTypes() {
  const files = fs.readdirSync(localesDir).filter((file) => file.endsWith('.json'))
  const packs = {}

  for (const file of files) {
    const part = path.basename(file, '.json')
    const content = JSON.parse(fs.readFileSync(path.join(localesDir, file), 'utf-8'))
    packs[part] = content
  }

  const { content, keyPathCount } = buildTypeContent(packs)
  fs.writeFileSync(outputPath, content)
  console.log(`[i18n] Generated types to ${outputPath} (${keyPathCount} key paths)`)
}

generateTypes()
